            ),
            DzikirItem(
            id = "nashr_06",
            category = DzikirCategory.HIZIB_NASHR,
            orderNumber = 6,
            title = "Hizib An-Nashr - Bagian 6: Syair Ghāratullāh & Penutup Ayat Al-Qur'an",
            arabicText = "لَا إِلَٰهَ إِلَّا أَنْتَ سُبْحَانَكَ إِنِّي كُنْتُ مِنَ الظَّالِمِينَ (٣ مرات)\n\nنَسْأَلُكَ بِأَسْرَارِ هَٰذِهِ الدَّعَوَاتِ الْمُسْتَجَابَاتِ أَنْ تَتَقَبَّلَ مِنَّا مَا بِهِ دَعَوْنَاكَ، وَأَنْ تُعْطِيَنَا مَا سَأَلْنَاكَ، أَنْجِزْ لَنَا وَعْدَكَ الَّذِي وَعَدْتَهُ لِعِبَادِكَ الْمُؤْمِنِينَ: لَا إِلَٰهَ إِلَّا أَنْتَ سُبْحَانَكَ إِنِّي كُنْتُ مِنَ الظَّالِمِينَ. انْقَطَعَتْ آمَالُنَا وَعِزَّتِكَ إِلَّا مِنْكَ، وَخَابَ رَجَاؤُنَا وَحَقِّكَ إِلَّا فِيكَ. إِنْ أَبْطَأَتْ غَارَةُ الْأَرْحَامِ وَابْتَعَدَتْ، فَأَقْرَبُ الشَّيْءِ مِنَّا غَارَةُ اللَّهِ. يَا غَارَةَ اللَّهِ جِدِّي السَّيْرَ مُسْرِعَةً فِي حَلِّ عُقْدَتِنَا، يَا غَارَةَ اللَّهِ.\nيَا غَارَةَ اللَّهِ حُلِّي عُقْدَ مَا رَبَطُوا ۝ وَشَتِّتِي شَمْلَ أَقْوَامٍ بِنَا اخْتَلَطُوا\nاللَّهُ أَكْبَرُ سَيْفُ اللَّهِ قَاطِعُهُمْ ۝ وَكُلَّمَا عَلَوْا فِي أَمْرِهِمْ هَبَطُوا\nعَدَتِ الْعَادُونَ وَجَارُوا، وَرَجَوْنَا اللَّهَ مُجِيرًا، وَكَفَىٰ بِاللَّهِ وَلِيًّا، وَكَفَىٰ بِاللَّهِ نَصِيرًا. حَسْبُنَا اللَّهُ وَنِعْمَ الْوَكِيلُ (٣ مرات). وَلَا حَوْلَ وَلَا قُوَّةَ إِلَّا بِاللَّهِ الْعَلِيِّ الْعَظِيمِ.\nاسْتَجِبْ لَنَا، آمِينَ، آمِينَ، آمِينَ.\nفَقُطِعَ دَابِرُ الْقَوْمِ الَّذِينَ ظَلَمُوا ۚ وَالْحَمْدُ لِلَّهِ رَبِّ الْعَالَمِينَ.\nوَصَلَّى اللَّهُ عَلَىٰ سَيِّدِنَا مُحَمَّدٍ وَعَلَىٰ آلِهِ وَصَحْبِهِ وَسَلَّمَ تَسْلِيمًا كَثِيرًا إِلَىٰ يَوْمِ الدِّينِ، وَالْحَمْدُ لِلَّهِ رَبِّ الْعَالَمِينَ",
            tajwidTags = "[o[لَا]] [o[إِلَٰهَ]] [o[إِلَّا]] [f[أَنتَ]] [q[سُبْ]]حَانَكَ [g[إِنِّي]] كُ[f[نتُ]] مِنَ [l[الظَّ]][p[الِمِينَ]] (٣ مرات)\n\n[l[نَسْ]]أَلُكَ بِ[o[أَسْرَارِ]] هَٰذِهِ [l[الدَّ]]عَوَاتِ الْمُ[l[سْ]]تَجَابَاتِ [a[أَن]] [a[تَ]]تَ[q[قَ]]بَّلَ [g[مِنَّا]] مَا بِهِ دَعَوْنَاكَ، [a[وَأَن]] [f[تُ]][q[عْ]][q[طِ]]يَنَا مَا سَأَلْنَاكَ، [o[أَن]][q[جِ]][q[زْ]] لَنَا وَعْدَكَ الَّذِي وَعَ[q[دْ]]تَهُ لِعِبَادِكَ الْمُؤْمِنِينَ: [o[لَا]] [o[إِلَٰهَ]] [o[إِلَّا]] [f[أَنتَ]] [q[سُبْ]]حَانَكَ [g[إِنِّي]] كُ[f[نتُ]] مِنَ [l[الظَّ]]الِمِينَ. [l[انْ]][q[قَ]]طَعَتْ [o[آمَالُنَا]] وَعِ[g[زَّ]]تِكَ [o[إِلَّا]] [f[مِنم]]كَ، وَخَابَ رَجَا[o[ؤُنَا]] وَحَ[g[قِّ]]كَ [o[إِلَّا]] فِيكَ. [a[إِنْ]] [o[أَ]][q[بْ]]طَأَتْ غَارَةُ الْأَرْحَامِ وَ[l[ابْ]]تَعَدَتْ، فَ[o[أَ]][q[قْ]]رَبُ [l[الشَّ]]يْءِ [g[مِنَّا]] غَارَةُ اللَّهِ. يَا غَارَةَ اللَّهِ جِ[g[دِّي]] [l[السَّ]]يْرَ مُسْرِعَةً فِي حَلِّ عُ[q[قْ]]دَتِنَا، يَا غَارَةَ اللَّهِ.\nيَا غَارَةَ اللَّهِ حُ[g[لِّي]] عُ[q[قْ]]دَ مَا رَبَطُوا ۝ وَشَ[g[تِّ]]تِي شَمْلَ [o[أَقْوَامٍ]] بِنَا [l[اخْ]]تَلَطُوا\nاللَّهُ [q[أَكْ]]بَرُ سَيْفُ اللَّهِ [o[قَاطِعُهُمْ]] ۝ وَكُ[g[لَّ]]مَا عَلَوْا فِي [o[أَمْرِهِمْ]] هَبَطُوا\nعَدَتِ الْعَادُونَ وَجَارُوا، وَرَجَوْنَا اللَّهَ مُجِي[a[رًا]]، [a[وَ]]كَفَىٰ بِاللَّهِ وَلِ[a[يًّا]]، [a[وَ]]كَفَىٰ بِاللَّهِ [p[نَصِيرًا]]. حَسْبُنَا اللَّهُ وَنِعْمَ [p[الْوَكِيلُ]] (٣ مرات). وَلَا حَوْلَ وَلَا قُوَّةَ [o[إِلَّا]] بِاللَّهِ الْعَلِيِّ الْعَظِيمِ.\n[l[اسْ]]تَ[q[جِ]][q[بْ]] لَنَا، [o[آمِينَ]]، [o[آمِينَ]]، [o[آمِينَ]].\nفَقُطِعَ دَابِرُ الْقَوْمِ الَّذِينَ ظَلَمُوا ۚ وَالْحَمْدُ لِلَّهِ رَبِّ [p[الْعَالَمِينَ]].\nوَصَلَّى اللَّهُ عَلَىٰ سَيِّدِنَا مُحَ[g[مَّ]]دٍ [o[وَعَلَىٰ]] [o[آلِهِ]] وَصَحْبِهِ وَسَلَّمَ تَسْلِي[f[مًا]] [f[كَ]]ثِي[a[رًا]] [o[إِلَىٰ]] يَوْمِ [l[الدِّ]][p[ينِ]]، وَالْحَمْدُ لِلَّهِ رَبِّ [p[الْعَالَمِينَ]]",
            transliteration = "Lā ilāha illā angta subḥānaka innī kuntu minaẓ-ẓālimīn (3x). Nas’aluka bi-asrāri hādzihid-da‘awātil-mustajābāti an tataqabbala minnā mā bihī da‘aunāk, wa an tu‘ṭhiyanā mā sa’alnāk, anjiz lanā wa‘dakal-ladzī wa‘adtahū li-‘ibādikal-mu’minīn: Lā ilāha illā angta subḥānaka innī kuntu minaẓ-ẓālimīn. Ingqaṭha‘at āmālunā wa ‘izzatika illā mingk, wa khāba rajā’unā wa ḥaqqika illā fīk. In abṭha’at ghāratul-arḥāmi wabta‘adat, fa-aqrabusy-syai’i minnā ghāratullāh. Yā ghāratallāhi jiddīs-saira musri‘atan fī ḥalli ‘uqdatinā, yā ghāratallāh.\nYā ghāratallāhi ḥullī ‘uqda mā rabaṭhū, wa syattitī syamla aqwāmim binakh-talaṭhū.\nAllāhu akbaru saifullāhi qāṭhi‘uhum, wa kullamā ‘alau fī amrihim habaṭhū.\n‘Adatil-‘ādūna wa jārū, wa rajaunallāha mujīrā, wa kafā billāhi waliyyā, wa kafā billāhi naṣīrā. Ḥasbunallāhu wa ni‘mal-wakīl (3x). Wa lā ḥaula wa lā quwwata illā billāhil-‘aliyyil-‘aẓīm. Istajib lanā, āmīn, āmīn, āmīn. Faquṭhi‘a dābirul-qaumil-ladzīna ẓalamū, wal-ḥamdu lillāhi rabbil-‘ālamīn. Wa ṣallallāhu ‘alā sayyidinā Muḥammadiw wa ‘alā ālihī wa ṣaḥbihī wa sallama taslīman katsīran ilā yaumid-dīn, wal-ḥamdu lillāhi rabbil-‘ālamīn.",
            translationId = "Tidak ada tuhan selain Engkau, Mahasuci Engkau, sesungguhnya aku termasuk orang-orang yang zalim (3 kali). Kami memohon kepada-Mu dengan rahasia doa-doa yang mustajab ini agar Engkau berkenan menerima apa yang kami panjatkan dan memberi kami apa yang kami mohonkan. Penuhilah janji-Mu yang telah Engkau janjikan kepada hamba-hamba-Mu yang beriman... Wahai pertolongan Allah, bergegaslah melaju dengan cepat dalam menguraikan simpul kesulitan kami! Wahai pertolongan Allah, urailah simpul yang mereka ikat, dan cerai-beraikanlah perhimpunan kaum yang menyerang kami. Allah Mahabesar! Pedang Allah akan menebas mereka, dan setiap kali mereka meninggikan diri niscaya mereka dijatuhkan! Musuh telah melampaui batas dan berbuat zalim, dan kami mengharap Allah sebagai penyelamat. Cukuplah Allah sebagai pelindung dan cukuplah Allah sebagai penolong. Cukuplah Allah bagi kami dan Dia adalah sebaik-baik wakil (3 kali). Tiada daya dan tiada kekuatan melainkan dengan pertolongan Allah Yang Mahatinggi lagi Mahaagung. Kabulkanlah bagi kami, amin, amin, amin! Maka dibinasakanlah sampai ke akar-akarnya kaum yang zalim itu, dan segala puji bagi Allah Tuhan semesta alam (QS. Al-An'am: 45).",
            translationEn = "There is no deity except You; exalted are You. Indeed, I have been of the wrongdoers (3 times)... O raid of Allah, untie the knot of what they have tied, and scatter the unity of the peoples who have converged against us. Allah is the Greatest! The sword of Allah cuts them off, and whenever they rise high in their affair, they fall low!... So the people that committed wrong were eradicated. And praise to Allah, Lord of the worlds (QS. Al-An'am: 45)...",
            repeatCount = 1,
            sourceNote = "Hizib An-Nashr Asy-Syadzili, Majmu' Syarif",
            fadhilah = "Pertolongan kilat pertolongan Ilahi (gharatullah) saat menghadapi kepungan fitnah, bahaya zalim, dan kesulitan yang mengikat."
            )
        )
    }

