            title = "Hizib An-Nashr Al-Haddad - Bagian 1: Pembuka Fath & Perlindungan (QS. Al-Fath: 1-3)",
            arabicText = "بِسْمِ اللَّهِ الرَّحْمَٰنِ الرَّحِيمِ\nإِنَّا فَتَحْنَا لَكَ فَتْحًا مُّبِينًا ۝ لِّيَغْفِرَ لَكَ اللَّهُ مَا تَقَدَّمَ مِن ذَنبِكَ وَمَا تَأَخَّرَ وَيُتِمَّ نِعْمَتَهُ عَلَيْكَ وَيَهْدِيَكَ صِرَاطًا مُّسْتَقِيمًا ۝ وَيَنصُرَكَ اللَّهُ نَصْرًا عَزِيزًا ۝ وَكَانَ بِالْمُؤْمِنِينَ رَحِيمًا ۝ وَكَانَ عِندَ اللَّهِ وَجِيهًا ۝ وَجِيهًا فِي الدُّنْيَا وَالْآخِرَةِ وَمِنَ الْمُقَرَّبِينَ ۝ وَوَجَّهْتُ وَجْهِيَ لِلَّذِي فَطَرَ السَّمَاوَاتِ وَالْأَرْضَ حَنِيفًا وَمَا أَنَا مِنَ الْمُشْرِكِينَ",
            tajwidTags = "بِسْمِ اللَّهِ [l[ال]][l[رَّ]]حْمَٰنِ [l[ال]][p[رَّحِيمِ]]\n[g[إِنَّا]] فَتَحْنَا لَكَ فَتْ[a[حًا]] [a[مُّ]]بِي[p[نًا]] ۝ [u[لِّيَغْ]]فِرَ لَكَ اللَّهُ مَا تَ[q[قَ]][g[دَّ]]مَ [f[مِن]] [f[ذَ]][q[نبِ]]كَ وَمَا [o[تَأَخَّ]]رَ وَيُتِ[g[مَّ]] نِعْمَتَهُ عَلَيْكَ وَيَهْدِيَكَ صِرَا[a[طًا]] [a[مُّ]][p[سْتَقِيمًا]] ۝ [a[وَيَنصُ]]رَكَ اللَّهُ نَصْ[a[رًا]] [p[عَزِيزًا]] ۝ وَكَانَ بِالْمُؤْمِنِينَ [p[رَحِيمًا]] ۝ وَكَانَ [f[عِندَ]] اللَّهِ [p[وَجِيهًا]] ۝ وَجِي[f[هًا]] [f[فِي]] [l[الدُّ]]نْيَا وَالْآخِرَةِ وَمِنَ [p[الْمُقَرَّبِينَ]] ۝ وَوَ[g[جَّ]]هْتُ وَ[q[جْ]]هِيَ لِلَّذِي فَطَرَ [l[السَّ]]مَاوَاتِ وَالْأَرْضَ حَنِي[f[فًا]] [a[وَمَا]] [o[أَنَا]] مِنَ [p[الْمُشْرِكِينَ]]",
            transliteration = "Bismillāhir-raḥmānir-raḥīm. Innā fataḥnā laka fat-ḥam mubīnā, liyaghfira lakallāhu mā taqaddama min dzambika wa mā ta’akhkhara wa yutimma ni‘matahū ‘alaika wa yahdiyaka ṣirāṭham mustaqīmā, wa yangṣurakallāhu naṣran ‘azīzā. Wa kāna bil-mu’minīna raḥīmā, wa kāna ‘ingdallāhi wajīhā, wajīhan fid-dunyā wal-ākhirati wa minal-muqarrabīn. Wa wajjahtu wajhiya lilladzī faṭharas-samāwāti wal-arḍa ḥanīfaw wa mā anā minal-musyrikīn.",
            translationId = "Dengan nama Allah Yang Maha Pengasih lagi Maha Penyayang. Sungguh, Kami telah memberikan kepadamu kemenangan yang nyata, agar Allah mengampuni dosamu yang telah lalu dan yang akan datang serta menyempurnakan nikmat-Nya atasmu dan menunjukimu ke jalan yang lurus, dan agar Allah menolongmu dengan pertolongan yang perkasa (QS. Al-Fath: 1-3). Dan Dia Maha Penyayang kepada orang-orang mukmin. Dan dia adalah seorang yang terkemuka di sisi Allah, terkemuka di dunia dan akhirat serta termasuk orang-orang yang didekatkan. Dan aku hadapkan wajahku kepada Dzat yang menciptakan langit dan bumi dengan lurus, dan aku bukanlah termasuk orang-orang musyrik.",
            translationEn = "In the name of Allah, the Entirely Merciful, the Especially Merciful. Indeed, We have given you a clear conquest, that Allah may forgive for you what preceded of your sin and what will follow and complete His favor upon you and guide you to a straight path, and that Allah may aid you with a mighty victory (QS. Al-Fath: 1-3)...",
            repeatCount = 1,
            sourceNote = "Hizib An-Nashr Al-Imam Abdullah bin Alawi Al-Haddad",
            fadhilah = "Membuka pintu kemenangan hakiki, memancarkan wibawa keimanan, dan menghancurkan rintangan hidup."
            ),
            DzikirItem(
