            arabicText = "بِسْمِ اللَّهِ الرَّحْمَٰنِ الرَّحِيمِ\nنَصْرٌ مِّنَ اللَّهِ وَفَتْحٌ قَرِيبٌ ۗ وَبَشِّرِ الْمُؤْمِنِينَ ۝ يَا أَيُّهَا الَّذِينَ آمَنُوا كُونُوا أَنصَارَ اللَّهِ كَمَا قَالَ عِيسَى ابْنُ مَرْيَمَ لِلْحَوَارِيِّينَ مَنْ أَنصَارِي إِلَى اللَّهِ ۖ قَالَ الْحَوَارِيُّونَ نَحْنُ أَنصَارُ اللَّهِ.\nاللَّهُ لَا إِلَٰهَ إِلَّا هُوَ الْحَيُّ الْقَيُّومُ ۚ لَا تَأْخُذُهُ سِنَةٌ وَلَا نَوْمٌ ۚ لَّهُ مَا فِي السَّمَاوَاتِ وَمَا فِي الْأَرْضِ ۗ مَن ذَا الَّذِي يَشْفَعُ عِندَهُ إِلَّا بِإِذْنِهِ ۚ يَعْلَمُ مَا بَيْنَ أَيْدِيهِمْ وَمَا خَلْفَهُمْ ۖ وَلَا يُحِيطُونَ بِشَيْءٍ مِّنْ عِلْمِهِ إِلَّا بِمَا شَاءَ ۚ وَسِعَ كُرْسِيُّهُ السَّمَاوَاتِ وَالْأَرْضَ ۖ وَلَا يَئُودُهُ حِفْظُهُمَا ۚ وَهُوَ الْعَلِيُّ الْعَظِيمُ",
            tajwidTags = "بِسْمِ اللَّهِ [l[ال]][l[رَّ]]حْمَٰنِ [l[ال]][p[رَّحِيمِ]]\nنَ[q[صْ]][a[رٌ]] [f[مِّنَ]] اللَّهِ وَفَ[q[تْ]][f[حٌ]] [f[قَ]]رِي[q[بٌ]] ۗ وَبَ[g[شِّ]]رِ [p[الْمُؤْمِنِينَ]] ۝ [o[يَا]] [o[أَيُّهَا]] الَّذِينَ [o[آمَنُوا]] كُونُوا [o[أَنصَارَ]] اللَّهِ كَمَا قَالَ عِيسَى [l[ابْ]]نُ مَرْيَمَ لِلْحَوَارِ[g[يِّينَ]] [f[مَنْ]] [o[أَنصَارِي]] [o[إِلَى]] اللَّهِ ۖ قَالَ الْحَوَارِ[g[يُّونَ]] نَحْنُ [o[أَنصَارُ]] اللَّهِ.\n[g[اللَّ]]هُ [o[لَا]] [o[إِلَٰهَ]] [o[إِلَّا]] هُوَ الْحَيُّ [p[الْقَيُّومُ]] ۚ لَا تَأْخُذُهُ سِنَ[a[ةٌ]] [a[وَ]]لَا [p[نَوْمٌ]] ۚ لَّهُ مَا فِي [l[السَّ]]مَاوَاتِ وَمَا فِي الْأَرْضِ ۗ [f[مَن]] [f[ذَ]]ا الَّذِي يَشْفَعُ [f[عِندَ]]هُ إِلَّا بِإِذْنِهِ ۚ يَعْلَمُ مَا بَيْنَ أَيْدِيهِمْ وَمَا خَلْفَهُمْ ۖ وَلَا يُحِيطُونَ بِشَيْ[a[ءٍ]] [a[مِّنْ]] عِلْمِهِ إِلَّا بِمَا [o[شَاءَ]] ۚ وَسِعَ كُرْسِيُّهُ [l[السَّ]]مَاوَاتِ وَالْأَرْضَ ۖ وَلَا يَئُودُهُ حِفْظُهُمَا ۚ وَهُوَ [p[الْعَلِيُّ]] [p[الْعَظِيمُ]]",
            transliteration = "Bismillāhir-raḥmānir-raḥīm. Naṣrum minallāhi wa fat-ḥung qarīb, wa basysyiril-mu’minīn. Yā ayyuhalladzīna āmanū kūnū anṣārallāhi kamā qāla ‘Īsabnu Maryama lil-ḥawāriyyīna man anṣārī ilallāh, qālal-ḥawāriyyūna naḥnu anṣārullāh. Allāhu lā ilāha illā huwal-ḥayyul-qayyūm, lā ta’khudzuhū sinatuw wa lā naūm, lahū mā fis-samāwāti wa mā fil-arḍ, mang dzal-ladzī yasyfa‘u ‘ingdahū illā bi’idznih, ya‘lamu مَا baina aidīhim wa mā khalfahum, wa lā yuḥīṭūna bi syai’im min ‘ilmihī illā bimā syā’, wasi‘a kursiyyuhus-samāwāti wal-arḍ, wa lā ya’ūduhū ḥifẓuhumā, wa huwal-‘aliyyul-‘aẓīm.",
            translationId = "Dengan nama Allah Yang Maha Pengasih lagi Maha Penyayang. Pertolongan dari Allah dan kemenangan yang dekat; dan sampaikanlah kabar gembira kepada orang-orang mukmin. Wahai orang-orang yang beriman, jadilah kamu penolong-penolong (agama) Allah sebagaimana Isa putra Maryam telah berkata kepada pengikut-pengikutnya yang setia: 'Siapakah yang akan menjadi penolong-penolongku untuk (menegakkan agama) Allah?' Pengikut-pengikutnya yang setia itu berkata: 'Kamilah penolong-penolong (agama) Allah' (QS. As-Saff: 13-14). Allah, tidak ada tuhan selain Dia, Yang Mahahidup lagi terus-menerus mengurus makhluk-Nya...",
            translationEn = "Victory from Allah and an imminent conquest; and give good tidings to the believers... Allah! There is no deity except Him, the Ever-Living, the Sustainer of existence...",
            repeatCount = 1,
            sourceNote = "Hizib An-Nashr Al-Haddad",
            fadhilah = "Memperkokoh benteng keimanan dengan wasilah Ayat Kursi dan ayat pertolongan para hawariyyin."
            ),
            DzikirItem(
