            title = "Hizib An-Nashr Al-Haddad - Bagian 3: Ta'awudz dari Setiap Makhluk & Benteng Tauhid",
            arabicText = "أُعِيذُ نَفْسِي بِاللَّهِ تَعَالَى مِنْ كُلِّ مَا يَسْمَعُ بِأُذُنَيْنِ، وَيُبْصِرُ بِعَيْنَيْنِ، وَيَمْشِي بِرِجْلَيْنِ، وَيَبْطِشُ بِيَدَيْنِ، وَيَتَكَلَّمُ بِشَفَتَيْنِ. حَصَّنْتُ نَفْسِي بِاللَّهِ الْخَالِقِ الْأَكْبَرِ، مِنْ شَرِّ مَا أَخَافُ وَأَحْذَرُ، مِنَ الْجِنِّ وَالْإِنْسِ وَأَنْ يَحْضُرُونِ. عَزَّ جَارُهُ، وَجَلَّ ثَنَاؤُهُ، وَتَقَدَّسَتْ أَسْمَاؤُهُ، وَلَا إِلَٰهَ غَيْرُهُ",
            tajwidTags = "[o[أُعِيذُ]] نَفْسِي بِاللَّهِ تَعَالَىٰ [f[مِن]] كُ[g[لِّ]] مَا يَ[l[سْ]]مَعُ [a[بِأُذُنَيْنِ]]، [a[وَيُ]][q[بْ]]صِرُ بِعَيْنَيْنِ، وَيَمْشِي بِرِ[q[جْ]]لَيْنِ، وَيَ[q[بْ]][q[طِ]]شُ بِيَدَيْنِ، وَيَتَكَ[g[لَّ]]مُ بِشَفَتَيْنِ. حَ[g[صَّ]][f[نتُ]] نَفْسِي بِاللَّهِ الْخَالِقِ [q[الْأَكْ]]بَرِ، [f[مِن]] [f[شَ]]رِّ [o[مَا]] [o[أَخَافُ]] [o[وَأَحْ]]ذَرُ، مِنَ الْجِ[g[نِّ]] وَ[l[الْإِنسِ]] [a[وَأَن]] [a[يَ]][q[حْ]]ضُرُونِ. عَ[g[زَّ]] جَارُهُ، وَجَ[g[لَّ]] ثَنَا[o[ؤُهُ]]، وَتَ[q[قَ]][g[دَّ]]سَتْ [o[أَسْمَاؤُهُ]]، [o[وَلَا]] [o[إِلَٰهَ]] [p[غَيْرُهُ]]",
            transliteration = "U‘īdzu nafsī billāhi ta‘ālā ming kulli mā yasma‘u bi-udzunain, wa yubṣiru bi-‘ainain, wa yamsyī bi-rijlain, wa yabṭhīsyu bi-yadain, wa yatakallamu bi-syafātain. Ḥaṣṣantu nafsī billāhil-khāliqil-akbar, ming syarri mā akhāfu wa aḥdzar, minal-jinni wal-ingsi wa ay yaḥḍurūn. ‘Azza jāruh, wa jalla tsanā’uh, wa taqaddasat asmā’uh, wa lā ilāha ghairuh.",
            translationId = "Aku memohon perlindungan untuk diriku kepada Allah Ta'ala dari segala sesuatu yang mendengar dengan dua telinga, melihat dengan dua mata, berjalan dengan dua kaki, menyerang dengan dua tangan, dan berbicara dengan dua bibir. Aku bentengi diriku dengan Allah Sang Maha Pencipta Yang Mahabesar, dari kejahatan apa yang aku takuti dan aku khawatirkan, dari golongan jin dan manusia dan dari kedatangan mereka kepadaku. Sungguh mulia perlindungan-Nya, Mahaagung pujian-Nya, Mahasuci nama-nama-Nya, dan tiada tuhan selain Dia.",
            translationEn = "I seek refuge for myself in Allah the Most High from everything that hears with two ears, sees with two eyes, walks on two legs, strikes with two hands, and speaks with two lips. I fortify myself with Allah, the Supreme Creator, from the evil of what I fear and dread, from jinn and mankind...",
            repeatCount = 1,
            sourceNote = "Hizib An-Nashr Al-Haddad",
            fadhilah = "Membentengi panca indera dan anggota tubuh dari segala pandangan jahat ('ain), fitnah lidah, dan serangan fisik."
            ),
            DzikirItem(
            id = "haddad_nashr_04",
            category = DzikirCategory.HIZIB_NASHR_HADDAD,
            orderNumber = 4,
            title = "Hizib An-Nashr Al-Haddad - Bagian 4: Menolak Makar & Memadamkan Api Permusuhan",
            arabicText = "اللَّهُمَّ إِنِّي أَجْعَلُكَ فِي نُحُورِ أَعْدَائِي، وَأَعُوذُ بِكَ مِنْ شُرُورِهِمْ وَتَحَيُّلِهِمْ وَمَكْرِهِمْ وَمَكَائِدِهِمْ. أَطْفِئْ نَارَ مَنْ أَرَادَ بِي عَدَاوَةً مِنَ الْجِنِّ وَالْإِنْسِ، يَا حَافِظُ يَا حَفِيظُ، يَا كَافِي يَا مُحِيطُ، سُبْحَانَكَ يَا رَبِّ مَا أَعْظَمَ شَأْنَكَ وَأَعَزَّ سُلْطَانَكَ. تَحَصَّنْتُ بِاللَّهِ، وَبِأَسْمَاءِ اللَّهِ، وَبِآيَاتِ اللَّهِ، وَمَلَائِكَةِ اللَّهِ، وَأَنْبِيَاءِ اللَّهِ، وَرُسُلِ اللَّهِ، وَالصَّالِحِينَ مِنْ عِبَادِ اللَّهِ. حَصَّنْتُ نَفْسِي بِلَا إِلَٰهَ إِلَّا اللَّهُ مُحَمَّدٌ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَآلِهِ وَسَلَّمَ",
            tajwidTags = "[g[اللَّ]]هُمَّ [g[إِنِّي]] [o[أَ]][q[جْ]]عَلُكَ فِي نُحُورِ [o[أَعْدَائِي]]، [o[وَأَعُوذُ]] بِكَ [f[مِن]] شُرُورِهِمْ وَتَحَ[g[يُّ]]لِهِمْ وَمَ[q[كْ]]رِهِمْ وَمَكَا[o[ئِدِهِمْ]]. [o[أَ]][q[طْ]]فِ[q[ئْ]] نَارَ [f[مَنْ]] [o[أَرَادَ]] بِي عَدَاوَ[f[ةً]] [f[مِّنَ]] الْجِ[g[نِّ]] [l[وَالْإِنسِ]]، يَا حَافِظُ يَا حَفِيظُ، يَا كَافِي يَا مُحِي[q[طُ]]، [q[سُبْ]]حَانَكَ يَا رَ[g[بِّ]] [o[مَا]] [o[أَعْ]][q[ظَ]]مَ شَ[o[أْنَكَ]] [o[وَأَعَزَّ]] سُلْطَانَكَ. تَحَ[g[صَّ]][f[نتُ]] بِاللَّهِ، [o[وَبِأَسْمَاءِ]] اللَّهِ، [o[وَبِآيَاتِ]] اللَّهِ، وَمَلَا[o[ئِكَةِ]] اللَّهِ، [o[وَأَنبِيَاءِ]] اللَّهِ، وَرُسُلِ اللَّهِ، [l[وَالصَّ]]الِحِينَ مِنْ عِبَادِ اللَّهِ. حَ[g[صَّ]][f[نتُ]] نَفْسِي بِ[o[لَا]] [o[إِلَٰهَ]] [o[إِلَّا]] اللَّهُ مُحَ[g[مَّ]][a[دٌ]] [u[رَّ]]سُولُ اللَّهِ صَ[g[لَّ]]ى اللَّهُ عَلَيْهِ [o[وَآلِهِ]] [p[وَسَلَّمَ]]",
            transliteration = "Allāhumma innī aj‘aluka fī nuḥūri a‘dā’ī, wa a‘ūdzu bika ming syurūrihim wa taḥayyulihim wa makrihim wa makā’idihim. Aṭhfi’ nāra man arāda bī ‘adāwatam minal-jinni wal-ings, yā Ḥāfiẓu yā Ḥafīẓ, yā Kāfī yā Muḥīṭh, subḥānaka yā rabbi mā a‘ẓama sya’naka wa a‘azza sulṭhānaka. Taḥaṣṣantu billāh, wa bi-asmā’illāh, wa bi-āyātillāh, wa malā’ikatillāh, wa ambiyā’illāh, wa rusulillāh, waṣ-ṣāliḥīna min ‘ibādillāh. Ḥaṣṣantu nafsī bi-Lā ilāha illallāhu Muḥammadur Rasūlullāhi ṣallallāhu ‘alaihi wa ālihī wa sallam.",
            translationId = "Ya Allah, sesungguhnya aku menjadikan Engkau di leher-leher musuhku, dan aku berlindung kepada-Mu dari kejahatan mereka, tipu daya mereka, makar mereka, dan perangkap mereka. Padamkanlah api orang yang bermaksud memusuhiku dari golongan jin dan manusia. Wahai Dzat Yang Maha Menjaga, wahai Dzat Yang Maha Memelihara, wahai Dzat Yang Maha Mencukupi, wahai Dzat Yang Meliputi segala sesuatu! Mahasuci Engkau wahai Tuhanku, betapa agung urusan-Mu dan betapa perkasa kekuasaan-Mu. Aku membentengi diriku dengan Allah, nama-nama Allah, ayat-ayat Allah, para malaikat Allah, para nabi Allah, para rasul Allah, dan hamba-hamba Allah yang saleh. Aku bentengi diriku dengan La ilaha illallah Muhammadur Rasulullah shallallahu 'alaihi wa alihi wa sallam.",
            translationEn = "O Allah, I place You in the throats of my enemies, and I seek refuge in You from their evils, their schemes, their plots, and their traps. Extinguish the fire of whoever intends enmity against me among the jinn and mankind...",
