            sourceNote = "Hizib An-Nashr Al-Haddad",
            fadhilah = "Menjinakkan kemarahan lawan, memadamkan dendam kesumat, dan menolak konspirasi jahat."
            ),
            DzikirItem(
            id = "haddad_nashr_05",
            category = DzikirCategory.HIZIB_NASHR_HADDAD,
            orderNumber = 5,
            title = "Hizib An-Nashr Al-Haddad - Bagian 5: Penjagaan Mata Allah & Istighatsah Ghiyats",
            arabicText = "اللَّهُمَّ احْرُسْنِي بِعَيْنِكَ الَّتِي لَا تَنَامُ، وَاكْنُفْنِي بِكَنَفِكَ الَّذِي لَا يُرَامُ، وَارْحَمْنِي بِقُدْرَتِكَ عَلَيَّ فَلَا أَهْلِكُ وَأَنْتَ ثِقَتِي وَرَجَائِي. يَا غِيَاثَ الْمُسْتَغِيثِينَ (٣ مرات)، يَا دَرَكَ الْهَالِكِينَ (٣ مرات). اكْفِنِي شَرَّ كُلِّ طَارِقٍ يَطْرُقُ بِلَيْلٍ أَوْ نَهَارٍ، إِلَّا طَارِقًا يَطْرُقُ بِخَيْرٍ، إِنَّكَ عَلَىٰ كُلِّ شَيْءٍ قَدِيرٌ. بِسْمِ اللَّهِ أَرْقِي نَفْسِي مِنْ كُلِّ شَيْءٍ يُؤْذِينِي، وَمِنْ شَرِّ كُلِّ نَفْسٍ أَوْ عَيْنِ حَاسِدٍ اللَّهُ يَشْفِينِي. وَصَلَّى اللَّهُ عَلَىٰ سَيِّدِنَا مُحَمَّدٍ وَعَلَىٰ آلِهِ وَصَحْبِهِ وَسَلَّمَ، وَالْحَمْدُ لِلَّهِ رَبِّ الْعَالَمِينَ",
            tajwidTags = "[g[اللَّ]]هُمَّ [l[احْ]]رُ[l[سْ]]نِي بِعَيْنِكَ الَّتِي لَا [p[تَنَامُ]]، وَ[l[اكْ]]نُ[q[فْ]]نِي بِكَنَفِكَ الَّذِي لَا [p[يُرَامُ]]، وَ[l[ارْ]]حَمْنِي بِ[q[قُ]][q[دْ]]رَتِكَ عَلَ[g[يَّ]] فَلَا [o[أَهْلِكُ]] [f[وَأَنتَ]] ثِ[q[قَ]]تِي [p[وَرَجَائِي]]. يَا غِيَاثَ الْمُ[l[سْ]]تَغِيثِينَ (٣ مرات)، يَا دَرَكَ الْهَالِكِينَ (٣ مرات). [l[اكْ]]فِنِي شَرَّ كُ[g[لِّ]] طَارِ[a[قٍ]] [a[يَ]][q[طْ]]رُقُ بِلَيْلٍ [o[أَوْ]] نَهَارٍ، [o[إِلَّا]] طَارِ[f[قًا]] [a[يَ]][q[طْ]]رُقُ بِخَيْرٍ، [g[إِنَّ]]كَ عَلَىٰ كُ[g[لِّ]] شَيْ[f[ءٍ]] [f[قَ]][p[دِيرٌ]]. بِسْمِ اللَّهِ [o[أَرْقِي]] نَفْسِي [f[مِن]] كُ[g[لِّ]] شَيْ[a[ءٍ]] [a[يُ]]ؤْذِينِي، وَ[f[مِن]] [f[شَ]]رِّ كُ[g[لِّ]] نَ[q[فْ]][f[سٍ]] [o[أَوْ]] عَيْنِ حَاسِدٍ اللَّهُ [p[يَشْفِينِي]]. وَصَلَّى اللَّهُ عَلَىٰ سَيِّدِنَا مُحَ[g[مَّ]]دٍ [o[وَعَلَىٰ]] [o[آلِهِ]] وَصَحْبِهِ وَسَلَّمَ، وَالْحَمْدُ لِلَّهِ رَبِّ [p[الْعَالَمِينَ]]",
            transliteration = "Allāhummaḥ-rusnī bi-‘ainikal-latī lā tanām, waknufnī bi-kanafikāl-ladzī lā yurām, war-ḥamnī bi-qudratika ‘alayya fa lā ahliku wa angta tsiqatī wa rajā’ī. Yā Ghiyātsal-mustaghītsīn (3x), yā darakal-hālikīn (3x). Ikfinī syarra kulli ṭhāriqiy yaṭhruqu bi-lailin au nahār, illā ṭhāriqay yaṭhruqu bi-khair, innaka ‘alā kulli syai’ing qadīr. Bismillāhi arqī nafsī ming kulli syai’iy yu’dzīnī, wa ming syarri kulli nafsin au ‘aini ḥāsidinillāhu yasyfīnī. Wa ṣallallāhu ‘alā sayyidinā Muḥammadiw wa ‘alā ālihī wa ṣaḥbihī wa sallam, wal-ḥamdu lillāhi rabbil-‘ālamīn.",
            translationId = "Ya Allah, jagalah aku dengan mata-Mu yang tidak pernah tidur, lindungilah aku dengan naungan-Mu yang tidak dapat ditembus musuh, dan rahmatilah aku dengan kekuasaan-Mu atasku sehingga aku tidak binasa, sedangkan Engkau adalah kepercayaanku dan harapanku. Wahai Penolong orang-orang yang memohon pertolongan (3 kali), wahai Penyelamat orang-orang yang binasa (3 kali). Cukupkanlah bagiku dari kejahatan setiap musibah yang mengetuk di waktu malam atau siang, kecuali pengetuk yang datang membawa kebaikan, sesungguhnya Engkau Mahakuasa atas segala sesuatu. Dengan nama Allah aku meruqyah diriku dari segala sesuatu yang menyakitiku, dan dari kejahatan setiap jiwa atau pandangan mata yang dengki, semoga Allah menyembuhkanku. Semoga Allah melimpahkan rahmat dan keselamatan kepada junjungan kami Nabi Muhammad beserta keluarga dan sahabatnya, dan segala puji bagi Allah Tuhan semesta alam.",
            translationEn = "O Allah, guard me with Your eye that never sleeps, and shelter me with Your shelter that cannot be breached, and have mercy on me through Your power over me, so that I perish not while You are my reliance and my hope. O Succorer of those who cry for help (3 times)... With the name of Allah I recite healing over myself from everything that harms me...",
            repeatCount = 1,
            sourceNote = "Hizib An-Nashr Al-Haddad",
            fadhilah = "Perlindungan mata Ilahi dari musibah malam dan siang, serta ruqyah syar'iyyah penawar racun dan 'ain."
            )
        )
    }

